printf '%s\n' 'import json' 'import sys' '' 'try:' '    cfg = json.load(open(sys.argv[1]))' 'except Exception as err:' '    print("cannot load config:", err, file=sys.stderr)' '    sys.exit(2)' 'for key in ["app", "defaults"]:' '    if key not in cfg:' '        print("missing required key '\''" + key + "'\''", file=sys.stderr)' '        sys.exit(1)' 'print("ok")' > validate_config.py
